        D(3,5) = b * pow(e[4], 2.0) / 4.0 - b * e[0] * e[1] / 2.0 + b * e[2] * e[6] / 2.0 + b * e[3] * e[5] + b * e[4] * e[6] / 2.0 + b * e[2] * e[4] / 2.0 + b * e[0] * e[2] / 2.0 + b * e[1] * e[3] / 2.0;
        D(4,5) = b * e[1] * e[2] / 2.0 - b * pow(e[0], 2.0) / 4.0 + b * e[3] * e[4] / 2.0 + b * e[5] * e[6] / 2.0 + b * e[4] * e[5] + b * e[2] * e[3] / 2.0 + b * e[0] * e[1] / 2.0 + b * e[3] * e[6] / 2.0;
        D(5,5) = b * pow(e[2], 2.0) / 2.0 + b * pow(e[6], 2.0) / 2.0 + 3.0 / 4.0 * b * pow(e[5], 2.0) + b * e[4] * e[6] / 2.0 + b * pow(e[1], 2.0) / 2.0 + b * pow(e[0], 2.0) / 2.0 + b * pow(e[3], 2.0) / 2.0 + a + b * pow(e[4], 2.0) / 2.0;
        D(6,5) = b * e[2] * e[3] / 2.0 + b * e[5] * e[6] - b * pow(e[0], 2.0) / 4.0 + b * e[1] * e[2] / 2.0 + b * e[4] * e[5] / 2.0 + b * e[3] * e[4] / 2.0 + b * e[0] * e[1] / 2.0;
        D(0,6) = -b * e[1] * e[4] / 2.0 - b * e[0] * e[5] / 2.0 + b * pow(e[3], 2.0) / 4.0 + b * e[0] * e[6] + b * e[1] * e[5] / 2.0 + b * e[2] * e[4] / 2.0 - b * e[2] * e[3] / 2.0;
        D(1,6) = b * e[1] * e[6] + b * e[0] * e[5] / 2.0 + b * e[2] * e[5] / 2.0 - b * e[0] * e[4] / 2.0 - b * pow(e[2], 2.0) / 4.0 - b * e[1] * e[3] / 2.0 + b * e[3] * e[4] / 2.0;
        D(2,6) = b * e[0] * e[4] / 2.0 - b * e[1] * e[2] / 2.0 + b * e[3] * e[5] / 2.0 + b * e[1] * e[5] / 2.0 - b * e[0] * e[3] / 2.0 + b * pow(e[4], 2.0) / 4.0 + b * e[2] * e[6];
        D(3,6) = b * e[3] * e[6] + b * e[2] * e[5] / 2.0 + b * e[1] * e[4] / 2.0 - b * pow(e[1], 2.0) / 4.0 - b * e[0] * e[2] / 2.0 + b * e[0] * e[3] / 2.0 + b * e[4] * e[5] / 2.0;
        D(4,6) = b * pow(e[5], 2.0) / 4.0 + b * e[3] * e[5] / 2.0 + b * e[2] * e[4] / 2.0 + b * e[0] * e[2] / 2.0 - b * e[0] * e[1] / 2.0 + b * e[4] * e[6] + b * e[1] * e[3] / 2.0;
        D(5,6) = b * e[2] * e[3] / 2.0 + b * e[5] * e[6] - b * pow(e[0], 2.0) / 4.0 + b * e[1] * e[2] / 2.0 + b * e[4] * e[5] / 2.0 + b * e[3] * e[4] / 2.0 + b * e[0] * e[1] / 2.0;
        D(6,6) = b * pow(e[3], 2.0) / 2.0 + b * pow(e[1], 2.0) / 2.0 + b * pow(e[2], 2.0) / 2.0 + b * pow(e[5], 2.0) / 2.0 + b * pow(e[0], 2.0) / 2.0 + b * pow(e[4], 2.0) / 2.0 + a + 3.0 / 4.0 * b * pow(e[6], 2.0);
        break;
    default:
